#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_vector_reset_iterator_valid_vector(void) {
    // Setup: create a valid vector and modify its iterator position
    Vector* vec = helper_create_vector(10);
    TEST_ASSERT_NOT_NULL(vec);

    // Modify the iterator position by calling next() a few times
    // First, fill the vector with some values
    int values[] = {10, 20, 30};
    int fill_result = helper_fill_vector(vec, values, 3);
    TEST_ASSERT_EQUAL_INT(0, fill_result);

    // Call next() to advance the iterator
    int val1 = vec->contents[vec->current]; vec->current++;
    TEST_ASSERT_EQUAL_INT(10, val1);
    int val2 = vec->contents[vec->current]; vec->current++;
    TEST_ASSERT_EQUAL_INT(20, val2);

    // At this point, vec->current should be 2 (pointing to third element)
    // Now test the target function: vector_reset_iterator
    vector_reset_iterator(vec);

    // Verify that the iterator has been reset by calling next() again
    // It should return the first element (10) if reset worked
    int val_after_reset = vec->contents[vec->current]; vec->current++;
    TEST_ASSERT_EQUAL_INT(10, val_after_reset);

    // Cleanup
    helper_cleanup_vector(vec);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_vector_reset_iterator_valid_vector);
    return UNITY_END();
}

